const express = require('express');
const { Sequelize, QueryTypes } = require('sequelize');

const app = express();
app.use(express.json());
const sequelize = new Sequelize(process.env.PAYROLL_DB_URI);

app.patch('/api/payroll/employees/:empId/direct-deposit', async (req, res) => {
  const { empId } = req.params;
  const { routingNumber, accountNumber } = req.body;

  if (!routingNumber || !accountNumber) {
    return res.status(400).json({ error: 'Routing and account numbers required' });
  }

  // Ensure employee can only update their own direct deposit details unless they hold an HR role
  const isSelf = req.user.employeeId === empId;
  const isHrAdmin = req.user.roles && req.user.roles.includes('HR_PAYROLL_ADMIN');
  if (!isSelf && !isHrAdmin) {
    return res.status(403).json({ error: 'Unauthorized to modify direct deposit for another employee' });
  }

  try {
    const [results, metadata] = await sequelize.query(
      `UPDATE direct_deposit_accounts
       SET routing_number = :routingNumber, account_number = :accountNumber, updated_at = NOW()
       WHERE employee_id = :empId`,
      {
        replacements: { routingNumber, accountNumber, empId },
        type: QueryTypes.UPDATE
      }
    );

    return res.json({ status: 'Direct deposit preferences updated', employeeId: empId });
  } catch (err) {
    return res.status(500).json({ error: 'Payroll update error' });
  }
});

module.exports = app;
